import "server-only";
import { mkdir } from "node:fs/promises";
import path from "node:path";

export const STORAGE_DIR = path.resolve(process.cwd(), process.env.STORAGE_DIR || "./storage/videos");
export const FRAMES_DIR = path.resolve(process.cwd(), process.env.FRAMES_DIR || "./storage/frames");

export async function ensureStorageDir(dir = STORAGE_DIR) {
  await mkdir(dir, { recursive: true });
}

/** Storage keys are generated by us (uuid + extension); never trust a client path. */
export function storagePath(key: string, dir = STORAGE_DIR) {
  const p = path.join(dir, path.basename(key));
  if (!p.startsWith(dir + path.sep)) throw new Error("Invalid storage key");
  return p;
}

export function extensionFor(name: string, mimeType: string) {
  const fromName = path.extname(name).toLowerCase().replace(/[^.a-z0-9]/g, "");
  if (fromName && fromName.length <= 6) return fromName;
  const map: Record<string, string> = {
    "video/mp4": ".mp4",
    "video/webm": ".webm",
    "video/quicktime": ".mov",
    "video/x-matroska": ".mkv",
    "video/ogg": ".ogv",
  };
  return map[mimeType] ?? ".bin";
}
